SELECT md.id, md.customer_id, md.meal_date, md.meal_type, md.food_id, md.quantity, md.notes, md.caregiver_id, md.created_at, c.name as customer_name, f.food_name, f.unit as food_unit, f.price as food_price, f.calories_per_unit as food_calories, f.protein_content as food_protein, f.fat_content as food_fat, f.carb_content as food_carbs, u.real_name as caregiver_name, (md.quantity * f.price) as total_price, (md.quantity * f.calories_per_unit) as total_calories, (md.quantity * f.protein_content) as total_protein, (md.quantity * f.fat_content) as total_fat, (md.quantity * f.carb_content) as total_carbs FROM meal_diaries md JOIN customers c ON md.customer_id = c.id JOIN foods f ON md.food_id = f.id LEFT JOIN users u ON md.caregiver_id = u.id
AND md.customer_id = #{customerId}
AND md.meal_date = #{mealDate}
AND md.meal_type = #{mealType}
AND md.meal_date >= #{startDate}
AND md.meal_date <= #{endDate}
ORDER BY md.meal_date DESC, md.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM meal_diaries md
JOIN customers c ON md.customer_id = c.id
JOIN foods f ON md.food_id = f.id


        AND md.customer_id = #{customerId}


        AND md.meal_date = #{mealDate}


